#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Enemies;
using MVZ2.GameContent.Damages;
using MVZ2.Vanilla.Enemies;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2.Vanilla.StateMachine;
using MVZ2Logic.Entities;
using PVZEngine.Buffs;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Modifiers;
using PVZEngine.Models;

namespace MVZ2.GameContent.Enemies
{
    /// <summary>
    /// 橄榄球僵尸：出场时以 2 倍速度（1.5 × 2 = 3）冲撞，
    /// 碰到第一个阻挡者时停下播放冲撞动画，第 6 个逻辑帧结束时摧毁器械，
    /// 动画结束后拔出背后的剑，恢复 1.5 速度并进行两段挥砍（100 × 2）。
    /// 状态机与两段挥砍的分段时机见 FootballZombie_States.cs。
    /// </summary>
    [AutoEntityBehaviourDefinition(VanillaEnemyNames.footballZombie)]
    public partial class FootballZombie : EnemyBehaviour
    {
        public FootballZombie(string nsp, string name) : base(nsp, name)
        {
            // 冲刺速度用“乘算修饰器”实现：改一个属性，速度就跟着变，
            // 比每帧直接写速度属性干净（同骷髅马的先例）。
            AddModifier(new FloatModifier(VanillaEnemyProps.SPEED, NumberOperator.Multiply, PROP_CHARGE_MULTIPLIER));
        }

        public override void Init(Entity entity)
        {
            base.Init(entity);
            SetCharged(entity, false);
            SetImpactTarget(entity, null);
            SetSwordDrawn(entity, false);
            entity.SetModelProperty(PROP_SWORD_DRAWN, false);
            // 初始为冲刺状态：速度 ×2
            entity.SetProperty(PROP_CHARGE_MULTIPLIER, CHARGE_SPEED_MULTIPLIER);
            // 锁定基础移速，中性化随机速度 buff，保证冲撞 3 / 恢复 1.5 不被随机数干扰
            SetSpeed(entity, BASE_SPEED);
            stateMachine.Init(entity);
            stateMachine.StartState(entity, STATE_IDLE);
        }
        protected override void UpdateAI(Entity entity)
        {
            base.UpdateAI(entity);
            stateMachine.UpdateAI(entity);
        }
        protected override void UpdateLogic(Entity entity)
        {
            base.UpdateLogic(entity);
            stateMachine.UpdateLogic(entity);
        }
        public override void PostDeath(Entity entity, DeathInfo info)
        {
            base.PostDeath(entity, info);
            if (entity.WillRemoveOnDeath(info))
                return;
            stateMachine.StartState(entity, STATE_DEATH);
        }

        // 缓存冲撞发生时的目标。到第 6 个逻辑帧时只结算这个目标，
        // 不读取期间可能改变的近战目标。
        public static void BeginImpact(Entity entity)
        {
            var targetID = EnemyMeleeBehaviour.GetMeleeTarget(entity);
            SetImpactTarget(entity, targetID);
            SetCharged(entity, true);
            entity.SetProperty(PROP_CHARGE_MULTIPLIER, 1f);
            var velocity = entity.Velocity;
            velocity.x = 0;
            entity.Velocity = velocity;
        }

        public static void ResolveImpact(Entity entity)
        {
            var targetID = GetImpactTarget(entity);
            SetImpactTarget(entity, null);
            var target = targetID?.GetEntity(entity.Level);
            if (target == null || target.IsDead || target.Type != EntityTypes.PLANT)
                return;
            var effects = new DamageEffectList(VanillaDamageEffects.IMPACT, VanillaDamageEffects.INSTA_KILL);
            target.Die(effects, entity);
        }

        public static void DrawSword(Entity entity)
        {
            SetSwordDrawn(entity, true);
            entity.SetModelProperty(PROP_SWORD_DRAWN, true);
        }

        // 设置移速：写入速度属性，并把身上可能存在的“随机速度 buff”固定成 1 倍，
        // 保证 3 / 1.5 的节奏不被随机数干扰（照撑杆跳的写法）。
        private static void SetSpeed(Entity entity, float speed)
        {
            entity.SetProperty(VanillaEnemyProps.SPEED, speed);
            foreach (var buff in entity.GetBuffs<RandomEnemySpeedBuff>())
            {
                RandomEnemySpeedBuff.SetSpeed(buff, 1);
            }
        }

        public static bool IsCharged(Entity entity) => entity.GetBehaviourField<bool>(PROP_CHARGED);
        public static void SetCharged(Entity entity, bool value) => entity.SetBehaviourField(PROP_CHARGED, value);
        public static EntityID? GetImpactTarget(Entity entity) => entity.GetBehaviourField<EntityID>(FIELD_IMPACT_TARGET);
        public static void SetImpactTarget(Entity entity, EntityID? value) => entity.SetBehaviourField(FIELD_IMPACT_TARGET, value);
        public static bool IsSwordDrawn(Entity entity) => entity.GetBehaviourField<bool>(FIELD_SWORD_DRAWN);
        public static void SetSwordDrawn(Entity entity, bool value) => entity.SetBehaviourField(FIELD_SWORD_DRAWN, value);

        public const float BASE_SPEED = 1.5f;                     // 冲撞结束后的行进速度（倍普僵）
        public const float CHARGE_SPEED_MULTIPLIER = 2f;          // 冲刺阶段速度倍率：1.5 × 2 = 3
        public const int IMPACT_HIT_TICKS = 4;                    // 第 4 个逻辑帧结束时摧毁器械
        public const int IMPACT_DURATION_TICKS = 92;             // impact 动画 5 秒 × 30 TPS
        public const string PROP_SWORD_DRAWN = "SwordDrawn";
        public static readonly VanillaEntityPropertyMeta<bool> PROP_CHARGED = new VanillaEntityPropertyMeta<bool>("charged");
        public static readonly VanillaEntityPropertyMeta<float> PROP_CHARGE_MULTIPLIER = new VanillaEntityPropertyMeta<float>("charge_multiplier");
        public static readonly VanillaEntityPropertyMeta<EntityID> FIELD_IMPACT_TARGET = new VanillaEntityPropertyMeta<EntityID>("FootballImpactTarget");
        public static readonly VanillaEntityPropertyMeta<bool> FIELD_SWORD_DRAWN = new VanillaEntityPropertyMeta<bool>("FootballSwordDrawn");
        private static EntityStateMachine stateMachine = new FootballStateMachine();
    }
}
